// -------------------------------------------------------------- manifest

/// One row per declared operation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OperationInfo {
    pub key: &'static str,
    pub path: &'static str,
    pub methods: &'static [&'static str],
    pub delivery: Delivery,
    /// Which wires may carry this operation.
    pub transports: &'static [&'static str],
    /// "unary", "server_stream", "client_stream", or "bidi".
    pub stream: &'static str,
}

/// Every operation in the route map, in declaration order.
pub const OPERATIONS: [OperationInfo; 11] = [
    OperationInfo { key: "healthz", path: "/healthz", methods: &["GET"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "create_matter", path: "/v1/matters", methods: &["POST"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "get_matter", path: "/v1/matters/{id}", methods: &["GET"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "walk_matter", path: "/v1/matters/{id}/walk", methods: &["POST"], delivery: Delivery::OptoSyncQueued, transports: &["http"], stream: "unary" },
    OperationInfo { key: "get_documents", path: "/v1/matters/{id}/documents", methods: &["GET"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "get_facts", path: "/v1/matters/{id}/facts", methods: &["GET"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "avenues", path: "/v1/avenues", methods: &["GET"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "geography", path: "/v1/geography", methods: &["GET"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "CheckFieldSanity", path: "/pmap.v1.Interview/CheckFieldSanity", methods: &["POST"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "AskCounsel", path: "/pmap.v1.Interview/AskCounsel", methods: &["POST"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
    OperationInfo { key: "check_field_sanity_rest", path: "/v1/fields/sanity", methods: &["POST"], delivery: Delivery::Direct, transports: &["http"], stream: "unary" },
];

